#!/usr/bin/env python3
"""Builds the VJN6 default bank (SPEC §15.3).

Reads the readable patch files in banks/default/*.json and writes
  banks/vjn6-default.vjn6bank   (canonical .vjn6bank, R-D3)
  core/state/default_bank.inc   (the same bank compiled into vjn6_core for first-run state)

Slot 1 and every slot without a file is INIT (R-P7). Run from anywhere:
  python3 tools/make_default_bank.py [--check]
--check exits non-zero if the generated files differ from the committed ones.
"""
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
SLIDERS = ["lfo_rate", "lfo_delay", "dco_lfo", "dco_pwm", "noise", "vcf_freq", "vcf_res", "vcf_env",
           "vcf_lfo", "vcf_kybd", "vca_level", "env_a", "env_d", "env_s", "env_r", "sub_level"]
SWITCHES = ["range", "pulse", "saw", "sub", "chorus", "pwm_src", "vcf_pol", "vca_mode", "hpf"]


def init_patch():
    s = [0] * 16
    s[5] = 127   # VCF FREQ
    s[10] = 127  # VCA LEVEL
    s[13] = 127  # SUSTAIN
    w = {"range": 1, "pulse": 0, "saw": 1, "sub": 1, "chorus": 0, "pwm_src": 0, "vcf_pol": 0,
         "vca_mode": 0, "hpf": 0}
    return {"name": "INIT", "sliders": s, "switches": w}


def load_bank():
    bank = [init_patch() for _ in range(128)]
    for f in sorted((ROOT / "banks" / "default").glob("*.json")):
        d = json.loads(f.read_text(encoding="utf-8"))
        slot = int(d["slot"])
        assert 2 <= slot <= 128, f
        sliders = [int(d["sliders"][k]) for k in SLIDERS]
        switches = {k: int(d["switches"][k]) for k in SWITCHES}
        assert all(0 <= v <= 127 for v in sliders + list(switches.values())), f
        bank[slot - 1] = {"name": d["name"][:12].rstrip(" "), "sliders": sliders, "switches": switches}
    return bank


def canonical_bank(bank):
    return json.dumps({"vjn6": 1, "patches": bank}, indent=2, ensure_ascii=True) + "\n"


def inc_file(bank):
    lines = ["// Generated by tools/make_default_bank.py from banks/default/*.json. Do not edit.",
             "struct DefaultSlotData { const char* name; unsigned char v[25]; };",
             "const DefaultSlotData kDefaultBankData[128] = {"]
    for p in bank:
        vals = p["sliders"] + [p["switches"][k] for k in SWITCHES]
        lines.append('    {"%s", {%s}},' % (p["name"], ", ".join(str(v) for v in vals)))
    lines.append("};")
    return "\n".join(lines) + "\n"


def main():
    bank = load_bank()
    outputs = {
        ROOT / "banks" / "vjn6-default.vjn6bank": canonical_bank(bank),
        ROOT / "core" / "state" / "default_bank.inc": inc_file(bank),
    }
    if "--check" in sys.argv:
        bad = [str(p) for p, txt in outputs.items() if not p.exists() or p.read_text(encoding="utf-8") != txt]
        if bad:
            print("out of date:", *bad)
            return 1
        print("default bank up to date")
        return 0
    for p, txt in outputs.items():
        p.write_text(txt, encoding="utf-8", newline="\n")
        print("wrote", p.relative_to(ROOT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
